const handleSubmitWeight = async () => {
  if (!selectedCompetition || !weighInForm.pegNumber || !weighInForm.pounds || !weighInForm.ounces) {
    toast({
      title: "Error",
      description: "Please enter peg number, pounds, and ounces.",
      variant: "destructive",
    });
    return;
  }

  const pegNumber = parseInt(weighInForm.pegNumber);
  const pounds = parseInt(weighInForm.pounds);
  const ounces = parseInt(weighInForm.ounces);

  // Validate numeric values
  if (!Number.isFinite(pounds) || !Number.isFinite(ounces) || pounds < 0 || ounces < 0) {
    toast({
      title: "Invalid weight",
      description: "Please select valid pounds and ounces.",
      variant: "destructive",
    });
    return;
  }

  // Check if at least some weight is entered
  if (pounds === 0 && ounces === 0) {
    toast({
      title: "Invalid weight",
      description: "Weight must be greater than 0.",
      variant: "destructive",
    });
    return;
  }

  // Convert to total ounces for storage
  const totalOunces = convertToOunces(pounds, ounces);

  // Upload fish photo if present
  let fishPhotoUrl: string | null = null;
  if (fishPhotoFile) {
    try {
      fishPhotoUrl = await uploadFishPhoto(fishPhotoFile);
    } catch (err) {
      toast({
        title: "Photo upload failed",
        description: "Weight will be submitted without the photo.",
        variant: "destructive",
      });
    }
  }

  // Handle team competitions with "Assign to Team" mode (shared peg)
  if (selectedCompetition.competitionMode === "team" && selectedCompetition.teamPegAssignmentMode === "team") {
    // Find team assigned to this peg
    const team = teams.find(t => t.pegNumber === pegNumber);

    if (!team) {
      toast({
        title: "Error",
        description: `No team assigned to peg ${pegNumber}`,
        variant: "destructive",
      });
      return;
    }

    // Submit to database with teamId instead of userId
    submitWeightMutation.mutate({
      competitionId: selectedCompetition.id,
      teamId: team.id,
      pegNumber: pegNumber,
      weight: totalOunces.toString(),
      fishPhotoUrl,
    });
  } else if (selectedCompetition.competitionMode === "team" && selectedCompetition.teamPegAssignmentMode === "members") {
    // Team competitions with "Assign to Members" mode - find participant and their team
    const participant = participants.find(p => p.pegNumber === pegNumber);

    if (!participant) {
      toast({
        title: "Error",
        description: `No team member assigned to peg ${pegNumber}`,
        variant: "destructive",
      });
      return;
    }

    // Find the team this participant belongs to
    const participantTeam = teams.find(t => 
      t.members?.some((m: any) => m.userId === participant.userId)
    );

    // Submit with both userId and teamId for team competitions
    const submitData: any = {
      competitionId: selectedCompetition.id,
      userId: participant.userId,
      pegNumber: pegNumber,
      weight: totalOunces.toString(),
      fishPhotoUrl,
    };

    // Include teamId if found to enable team-based grouping in leaderboard
    if (participantTeam) {
      submitData.teamId = participantTeam.id;
    }

    submitWeightMutation.mutate(submitData);
  } else {
    // Individual competitions
    const participant = participants.find(p => p.pegNumber === pegNumber);

    if (!participant) {
      toast({
        title: "Error",
        description: `No angler assigned to peg ${pegNumber}`,
        variant: "destructive",
      });
      return;
    }

    // Submit to database (weight stored as total ounces in string format)
    submitWeightMutation.mutate({
      competitionId: selectedCompetition.id,
      userId: participant.userId,
      pegNumber: pegNumber,
      weight: totalOunces.toString(),
      fishPhotoUrl,
    });
  }

  // Clear fish photo after submission
  setFishPhotoFile(null);
  setFishPhotoPreview("");
};

